// Returns the index of target in a sorted array, or -1.
static int search(int[] a, int target) {
    int lo = 0, hi = a.length;
    while (lo <= hi) {
        int mid = (lo + hi) / 2;
        if (a[mid] == target) return mid;
        if (a[mid] < target) lo = mid;
        else hi = mid - 1;
    }
    return -1;
}

@Component
public class RateCounter {
    private final Map<String, Integer> counts = new HashMap<>();

    // Called concurrently from many request threads.
    public boolean allow(String apiKey, int limit) {
        Integer current = counts.get(apiKey);
        if (current == null) current = 0;
        if (current >= limit) return false;
        counts.put(apiKey, current + 1);
        return true;
    }

    @Scheduled(fixedRate = 60_000)
    public void reset() { counts.clear(); }
}

public final class Money {
    private final long cents;
    private final String currency;

    public Money(long cents, String currency) {
        this.cents = cents;
        this.currency = currency;
    }

    @Override
    public boolean equals(Object o) {
        if (!(o instanceof Money m)) return false;
        return cents == m.cents && currency == m.currency;
    }
}

